import{_ as e,o as i,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Setting Contradiction Self-Check List","description":"","frontmatter":{},"headers":[],"relativePath":"en/0097-设定矛盾自查表.md","filePath":"en/0097-设定矛盾自查表.md"}'),a={name:"en/0097-设定矛盾自查表.md"};function o(r,t,d,c,h,l){return i(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="setting-contradiction-self-check-list" tabindex="-1">Setting Contradiction Self-Check List <a class="header-anchor" href="#setting-contradiction-self-check-list" aria-label="Permalink to &quot;Setting Contradiction Self-Check List&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document number</td><td>97</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core keywords</td><td>contradiction self-check, setting consistency, logical verification, quality control, setting maintenance</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>The Setting Contradiction Self-Check List is the quality control tool of the setting system of the Anchor Symbiotic Civilization, used to systematically identify possible setting contradictions and logical inconsistencies when creating new settings, revising old settings, and updating documents. This self-check list is compiled on the basis of the 14 core settings and the consistency check list established in SPEC.md, covering all modules including the worldview, the cultivation system, the social system, the legal system, life forms, the technological system, historical eras, and cross-plane interaction. Any new setting or revised content must pass all check items of this self-check list before being formally incorporated into the setting system.</p><h2 id="ii-core-setting-consistency-checks" tabindex="-1">II. Core Setting Consistency Checks <a class="header-anchor" href="#ii-core-setting-consistency-checks" aria-label="Permalink to &quot;II. Core Setting Consistency Checks&quot;">​</a></h2><h3 id="_2-1-universe-names-and-basic-concepts" tabindex="-1">2.1 Universe Names and Basic Concepts <a class="header-anchor" href="#_2-1-universe-names-and-basic-concepts" aria-label="Permalink to &quot;2.1 Universe Names and Basic Concepts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>C01</td><td>Whether the universe name is unified</td><td>The full text uniformly uses &quot;Wanling Hengmao Origin Universe&quot; or the abbreviation &quot;Hengyuan Universe&quot;; no other names may be used</td><td>Mixing non-standard names such as &quot;universe,&quot; &quot;ten thousand worlds,&quot; and &quot;all heavens&quot;</td></tr><tr><td>C02</td><td>Whether the definition of the Anchor is consistent</td><td>The Anchor is always defined as &quot;a stable node in the law network&quot;; its essential attributes may not be changed</td><td>Describing the Anchor as an object, creature, or energy body</td></tr><tr><td>C03</td><td>Whether the symbiosis concept is unified</td><td>Symbiosis always means &quot;the common evolution of different lives through mutually beneficial cooperation&quot;; deviation from the anti-predation stance is not allowed</td><td>Describing symbiosis as assimilation, annexation, or control</td></tr><tr><td>C04</td><td>Whether the core stance is consistent</td><td>Always uphold the principle of &quot;Reality as the Foundation&quot;; fictional settings may not be described as reality</td><td>Confusing the boundary between fiction and reality</td></tr></tbody></table><h3 id="_2-2-cultivation-system-consistency" tabindex="-1">2.2 Cultivation System Consistency <a class="header-anchor" href="#_2-2-cultivation-system-consistency" aria-label="Permalink to &quot;2.2 Cultivation System Consistency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>C05</td><td>Whether the total number of systems is consistent</td><td>The total number of Origin Cultivation Systems is always three hundred; it may not be increased or decreased</td><td>Vague expressions such as &quot;more than three hundred&quot; or &quot;several hundred&quot;</td></tr><tr><td>C06</td><td>Whether the system classification is consistent</td><td>Always divided into six major categories (Origin Deduction, Life Cycle, Spatial Legal Principle, Consciousness Ascension, Symbiotic Network, Applied Engineering), with fifty systems in each category</td><td>Other classification methods or inconsistent category counts</td></tr><tr><td>C07</td><td>Whether the Three Origin Foundations are consistent</td><td>The first three systems are always Deduction Iteration (001), Life Cycle (002), and Spatial Legal Principle Dispatch (003)</td><td>Changing the numbers or names of the first three systems</td></tr><tr><td>C08</td><td>Whether the Multiplying Fruit setting is consistent</td><td>The Multiplying Fruit is always an &quot;opening buff,&quot; providing a hundredfold deduction amplification, and has been technologically applied</td><td>Describing the Multiplying Fruit as a natural fruit or as not technologized</td></tr><tr><td>C09</td><td>Whether the cultivation realms are consistent</td><td>The realm divisions of each system remain consistent with Document 14 &quot;Unified Division of Cultivation Realms&quot;</td><td>Inventing realm names that contradict the unified division</td></tr><tr><td>C10</td><td>Whether the anti-predation stance is consistent</td><td>Predatory cultivation may not be described as a positive or acceptable system</td><td>Defending or beautifying predatory cultivation</td></tr></tbody></table><h3 id="_2-3-social-and-legal-consistency" tabindex="-1">2.3 Social and Legal Consistency <a class="header-anchor" href="#_2-3-social-and-legal-consistency" aria-label="Permalink to &quot;2.3 Social and Legal Consistency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>C11</td><td>Whether the civilization typologies are consistent</td><td>Always the Five Typologies (East Asian Intensive, Nordic Welfare, North American Pluralistic, Continental European Social, Developing Catch-up)</td><td>A sixth typology appears or the typology names are changed</td></tr><tr><td>C12</td><td>Whether the legal system is consistent</td><td>Always the Constitution + Labor Law + Consumer Protection Law + five supporting laws (education, medical care, housing, environment, antitrust)</td><td>Omitting a law or adding an unestablished law</td></tr><tr><td>C13</td><td>Whether the governance structure is consistent</td><td>Always the Anchor Assembly (legislature) + Symbiotic Executive Committee (executive) + Symbiotic Court (judiciary) + Anchor Oversight Committee (supervision)</td><td>Changing institution names or power distribution</td></tr><tr><td>C14</td><td>Whether the Output-Linked Contract Mechanism is consistent</td><td>Always centered on &quot;more work, more gain&quot;; resource allocation is based on contribution</td><td>Describing the Output-Linked Contract as egalitarianism or distribution according to need</td></tr><tr><td>C15</td><td>Whether the 20% Activation Strategy is consistent</td><td>Always activating 20% of living beings as Supreme Powers of the Plane in the early stage</td><td>Changing the activation ratio or goal</td></tr></tbody></table><h2 id="iii-cross-module-logical-consistency-checks" tabindex="-1">III. Cross-Module Logical Consistency Checks <a class="header-anchor" href="#iii-cross-module-logical-consistency-checks" aria-label="Permalink to &quot;III. Cross-Module Logical Consistency Checks&quot;">​</a></h2><h3 id="_3-1-timeline-consistency" tabindex="-1">3.1 Timeline Consistency <a class="header-anchor" href="#_3-1-timeline-consistency" aria-label="Permalink to &quot;3.1 Timeline Consistency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>L01</td><td>Whether the times of historical events are consistent</td><td>The times of all historical events remain consistent with Document 93 &quot;Chronology of Eras — Master Table&quot; and Documents 70–79</td><td>The same event has inconsistent times in different documents</td></tr><tr><td>L02</td><td>Whether the era division is consistent</td><td>The era names and start-end times remain consistent with Document 70 &quot;Chronology of Eras — Master Table&quot;</td><td>Unestablished eras appear or era boundaries are changed</td></tr><tr><td>L03</td><td>Whether the periods of figures are consistent</td><td>The active periods of key figures remain consistent with Document 95 &quot;Key Figures and Organizations&quot;</td><td>A figure appears in an era in which they did not exist</td></tr><tr><td>L04</td><td>Whether the times of technologies are consistent</td><td>The invention and maturation times of each technology remain consistent with the chronology</td><td>A technology is used in an era before its invention</td></tr></tbody></table><h3 id="_3-2-technological-system-consistency" tabindex="-1">3.2 Technological System Consistency <a class="header-anchor" href="#_3-2-technological-system-consistency" aria-label="Permalink to &quot;3.2 Technological System Consistency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>T01</td><td>Whether the Replication Mirror technology is consistent</td><td>The Replication Mirror is always &quot;a 1:1 replication device that does not touch the original,&quot; with zero interference in the replication process</td><td>Describing the Replication Mirror as capable of altering the original or requiring contact with the original</td></tr><tr><td>T02</td><td>Whether the isolated space is consistent</td><td>The isolated space is always &quot;an independent space completely separated from the outside by law barriers&quot;</td><td>Describing the isolated space as an ordinary room or virtual space</td></tr><tr><td>T03</td><td>Whether the Spatial Legal Principle cultivation requirements are consistent</td><td>The cultivation requirements of each spatial technology remain consistent with Document 13 &quot;Detailed Explanation of the Spatial Legal Principle Dispatch System&quot;</td><td>Low-realm cultivators use technologies requiring high realms</td></tr><tr><td>T04</td><td>Whether the energy units are consistent</td><td>Energy measurement uniformly uses the &quot;standard energy unit&quot;; no other units may be used</td><td>Mixing non-standard energy units such as &quot;spirit stones&quot; and &quot;crystal coins&quot;</td></tr></tbody></table><h3 id="_3-3-cross-plane-and-time-rules-consistency" tabindex="-1">3.3 Cross-Plane and Time Rules Consistency <a class="header-anchor" href="#_3-3-cross-plane-and-time-rules-consistency" aria-label="Permalink to &quot;3.3 Cross-Plane and Time Rules Consistency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>K01</td><td>Whether &quot;observe first, then intervene within limits&quot; is consistent</td><td>All time regression and cross-plane operations must follow this principle; the observation stage may not be skipped</td><td>Describing operations that intervene directly without observation</td></tr><tr><td>K02</td><td>Whether &quot;knowledge-only retrieval&quot; is consistent</td><td>Archaeological output is limited to abstract knowledge and information; matter, energy, or life forms may not be returned</td><td>Describing the act of bringing artifacts or samples back to the home plane</td></tr><tr><td>K03</td><td>Whether the traversal permit system is consistent</td><td>All plane traversal must obtain a permit of the corresponding level; traversal without a permit is not allowed</td><td>Describing unauthorized traversal</td></tr><tr><td>K04</td><td>Whether the time paradox classification is consistent</td><td>Paradoxes are always divided into four categories — parricide, information, ontological, and event; additions or changes are not allowed</td><td>Unestablished paradox types appear</td></tr><tr><td>K05</td><td>Whether the plane classification is consistent</td><td>Planes are always divided into five major categories (Material-Substance, Energy-Manifested, Consciousness-Dominated, Law-Fractured, Origin-Adjacent)</td><td>Other classification methods appear</td></tr></tbody></table><h3 id="_3-4-life-and-race-consistency" tabindex="-1">3.4 Life and Race Consistency <a class="header-anchor" href="#_3-4-life-and-race-consistency" aria-label="Permalink to &quot;3.4 Life and Race Consistency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>S01</td><td>Whether the race classification is consistent</td><td>Races are always divided into eight major categories (humanoid, beast, plant, elemental, energy, consciousness, mechanical, hybrid)</td><td>Other classification methods appear</td></tr><tr><td>S02</td><td>Whether the handling of Anomalous Life is consistent</td><td>Anomalous Life is always handled according to the three types of standardized handling procedures</td><td>Describing arbitrary handling outside the procedures</td></tr><tr><td>S03</td><td>Whether the handling of Dark Replacement Entities is consistent</td><td>Dark Replacement Entities are always handled according to the Dual-Soul Ethics and the four-branch handling rules</td><td>Describing the act of simply eliminating one soul</td></tr><tr><td>S04</td><td>Whether the equality of the Ten Thousand Races is consistent</td><td>All intelligent races are equal before the law; racial discrimination settings are not allowed</td><td>Describing a certain race as naturally inferior or deserving of enslavement</td></tr></tbody></table><h2 id="iv-document-format-and-specification-checks" tabindex="-1">IV. Document Format and Specification Checks <a class="header-anchor" href="#iv-document-format-and-specification-checks" aria-label="Permalink to &quot;IV. Document Format and Specification Checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check item</th><th>Check content</th><th>Pass standard</th><th>Common problems</th></tr></thead><tbody><tr><td>F01</td><td>Whether the file name format is correct</td><td>The file name format is &quot;XX-Document Title.md,&quot; where XX is a two-digit number</td><td>Missing number, title containing spaces, wrong file extension</td></tr><tr><td>F02</td><td>Whether the document information block is complete</td><td>The beginning contains an information table of number, module, and core keywords (3–5)</td><td>Missing information block or incomplete fields</td></tr><tr><td>F03</td><td>Whether the number of level-two headings meets the standard</td><td>The main body contains at least 3 sections with level-two headings</td><td>Fewer than 3 level-two headings</td></tr><tr><td>F04</td><td>Whether structured elements are used</td><td>Lists, tables, and other structured elements are used to enhance readability</td><td>Pure text paragraphs without lists or tables</td></tr><tr><td>F05</td><td>Whether the conclusion exists</td><td>A &quot;Conclusion&quot; paragraph exists at the end</td><td>Missing conclusion</td></tr><tr><td>F06</td><td>Whether the related documents exist</td><td>2–3 related document numbers and names are listed at the end</td><td>Missing related documents or the related documents do not exist</td></tr><tr><td>F07</td><td>Whether the word count meets the standard</td><td>The main body is no less than 800 characters (excluding headings and meta-information)</td><td>Main body below 800 characters</td></tr><tr><td>F08</td><td>Whether the terminology is unified</td><td>Standard terms such as &quot;Hengyuan Universe,&quot; &quot;Anchor,&quot; and &quot;Symbiosis&quot; are used</td><td>Ununified terminology or non-standard expressions</td></tr><tr><td>F09</td><td>Whether the writing style is appropriate</td><td>A serious, systematic setting-document style without colloquial expressions</td><td>Colloquial or casual expressions appear</td></tr><tr><td>F10</td><td>Whether the numbers are consistent with the list</td><td>The document numbers and titles are consistent with the complete list of 100 documents in SPEC.md</td><td>Numbers or titles inconsistent with the list</td></tr></tbody></table><h2 id="v-self-check-process-and-usage" tabindex="-1">V. Self-Check Process and Usage <a class="header-anchor" href="#v-self-check-process-and-usage" aria-label="Permalink to &quot;V. Self-Check Process and Usage&quot;">​</a></h2><h3 id="_5-1-self-check-process-for-new-setting-creation" tabindex="-1">5.1 Self-Check Process for New Setting Creation <a class="header-anchor" href="#_5-1-self-check-process-for-new-setting-creation" aria-label="Permalink to &quot;5.1 Self-Check Process for New Setting Creation&quot;">​</a></h3><ol><li><strong>Preliminary self-check</strong>: after the creation is completed, the creator checks item by item against this self-check list and marks the items with problems.</li><li><strong>Revision and improvement</strong>: revise the marked problem items to ensure all pass.</li><li><strong>Cross-review</strong>: submit to another setting creator for cross-review, focusing on cross-module consistency.</li><li><strong>Committee approval</strong>: major setting changes must be submitted to the Setting Maintenance Committee for approval.</li><li><strong>Archival update</strong>: after passing all checks, formally incorporate into the setting system and update the relevant index documents.</li></ol><h3 id="_5-2-self-check-process-for-revising-old-settings" tabindex="-1">5.2 Self-Check Process for Revising Old Settings <a class="header-anchor" href="#_5-2-self-check-process-for-revising-old-settings" aria-label="Permalink to &quot;5.2 Self-Check Process for Revising Old Settings&quot;">​</a></h3><ol><li><strong>Impact assessment</strong>: assess the other documents and setting modules that the revised content may affect.</li><li><strong>Related-document checks</strong>: conduct consistency checks on all affected related documents.</li><li><strong>Synchronized revision</strong>: revise the affected content in the related documents in synchronization.</li><li><strong>Version recording</strong>: record the revision content and version number in Document 99 &quot;Document Version and Maintenance Notes.&quot;</li><li><strong>Announcement notice</strong>: major revisions must publish a change announcement to all setting users.</li></ol><h3 id="_5-3-regular-comprehensive-self-check" tabindex="-1">5.3 Regular Comprehensive Self-Check <a class="header-anchor" href="#_5-3-regular-comprehensive-self-check" aria-label="Permalink to &quot;5.3 Regular Comprehensive Self-Check&quot;">​</a></h3><p>The Setting Maintenance Committee conducts a comprehensive setting consistency self-check every quarter, systematically checking all 100 documents to identify potential setting contradictions and logical inconsistencies. The self-check results form the &quot;Quarterly Setting Consistency Report,&quot; which is made public to all setting users.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Setting Contradiction Self-Check List is the &quot;quality constitution&quot; of the setting system of the Anchor Symbiotic Civilization. Through systematized, checklist-style check items, it ensures that the setting system always maintains logical self-consistency and terminology unification in the process of continuous expansion and revision. What a vast setting system fears most is not insufficient content richness, but rampant internal contradictions and inconsistency between earlier and later parts. The existence of this self-check list is precisely to ensure that the setting system of the Anchor Symbiotic Civilization, while maintaining openness and growth, always possesses a solid foundation of consistency.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>99-文档版本与维护说明 (Document Version and Maintenance Notes)</li><li>90-术语词典 (The Glossary)</li><li>00-衡元宙宇宙总览 (Heng Yuan Zhou: Cosmic Overview)</li></ul>',33)])])}const g=e(a,[["render",o]]);export{m as __pageData,g as default};
